.target sm_89
.address_size 64
// Cooperative tiled conv2d with 2x2 register blocking: each CTA computes a
// 32x32 output tile for one (batch, out_channel). The 3x34x34 bf16 input tile
// (row stride 36 to keep shared loads bank-conflict-light) and the 27 weights
// (pre-converted to f32) are staged in shared memory; each of the 256 threads
// then computes a 2x2 output patch from a 4x4 window loaded as 32-bit pairs,
// so every shared-memory load feeds four accumulators instead of one.
.extern .shared .align 4 .b8 smem_raw[];
.visible .entry conv2d_bf16_3x3(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_out
)
{
    .reg .pred %p, %q;
    .reg .b16 %h0;
    .reg .b32 %r_pair;
    .reg .f32 %f_w, %acc<4>, %fi<16>, %fw<9>;
    .reg .u32 %r_tid, %r_tx, %r_ty, %r_n, %r_oc;
    .reg .u32 %r_oh0, %r_ow0, %r_ly, %r_lx;
    .reg .u32 %r_e, %r_ic, %r_iy, %r_ix, %r_ih, %r_iw;
    .reg .u32 %r_off, %r_tmp, %r_i;
    .reg .u32 %r_sbase, %r_sinb, %r_saddr, %r_wb, %r_ibcur;
    .reg .u64 %rd_in, %rd_w, %rd_out, %rd_addr;
    ld.param.u64 %rd_in, [param_in];
    ld.param.u64 %rd_w, [param_w];
    ld.param.u64 %rd_out, [param_out];
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_tmp, %ctaid.x;
    rem.u32 %r_tx, %r_tmp, 7;
    div.u32 %r_ty, %r_tmp, 7;
    mov.u32 %r_oc, %ctaid.y;
    mov.u32 %r_n, %ctaid.z;
    mul.lo.u32 %r_oh0, %r_ty, 32;
    mul.lo.u32 %r_ow0, %r_tx, 32;
    mov.u32 %r_sbase, smem_raw;
    add.u32 %r_sinb, %r_sbase, 112;
    // stage the 27 weights of this output channel as f32 (threads 0..26)
    setp.ge.u32 %p, %r_tid, 27;
    @%p bra W_DONE;
    mad.lo.u32 %r_off, %r_oc, 27, %r_tid;
    mul.wide.u32 %rd_addr, %r_off, 2;
    add.u64 %rd_addr, %rd_w, %rd_addr;
    ld.global.b16 %h0, [%rd_addr];
    cvt.f32.bf16 %f_w, %h0;
    mad.lo.u32 %r_saddr, %r_tid, 4, %r_sbase;
    st.shared.f32 [%r_saddr], %f_w;
