    mov.u32 %r_i, 0;
TILE_LOOP:
    setp.ge.u32 %p, %r_i, 14;
    @%p bra TILE_DONE;
    mad.lo.u32 %r_e, %r_i, 256, %r_tid;
    setp.ge.u32 %p, %r_e, 3468;
    @%p bra TILE_NEXT;
    div.u32 %r_ic, %r_e, 1156;
    rem.u32 %r_tmp, %r_e, 1156;
    div.u32 %r_iy, %r_tmp, 34;
    rem.u32 %r_ix, %r_tmp, 34;
    add.u32 %r_ih, %r_oh0, %r_iy;
    add.u32 %r_iw, %r_ow0, %r_ix;
    mov.b16 %h0, 0;
    setp.ge.u32 %p, %r_ih, 224;
    @%p bra STORE_ELEM;
    setp.ge.u32 %p, %r_iw, 224;
    @%p bra STORE_ELEM;
