    ld.shared.f32 %fw2, [%r_wb+8];
    ld.shared.f32 %fw3, [%r_wb+12];
    ld.shared.f32 %fw4, [%r_wb+16];
    ld.shared.f32 %fw5, [%r_wb+20];
    ld.shared.f32 %fw6, [%r_wb+24];
    ld.shared.f32 %fw7, [%r_wb+28];
    ld.shared.f32 %fw8, [%r_wb+32];
