    ld.shared.b32 %r_pair, [%r_ibcur+0];
    shl.b32 %fi0, %r_pair, 16;
    and.b32 %fi1, %r_pair, 0xffff0000;
    ld.shared.b32 %r_pair, [%r_ibcur+4];
    shl.b32 %fi2, %r_pair, 16;
    and.b32 %fi3, %r_pair, 0xffff0000;
    ld.shared.b32 %r_pair, [%r_ibcur+72];
    shl.b32 %fi4, %r_pair, 16;
    and.b32 %fi5, %r_pair, 0xffff0000;
    ld.shared.b32 %r_pair, [%r_ibcur+76];
    shl.b32 %fi6, %r_pair, 16;
    and.b32 %fi7, %r_pair, 0xffff0000;
    ld.shared.b32 %r_pair, [%r_ibcur+144];
    shl.b32 %fi8, %r_pair, 16;
    and.b32 %fi9, %r_pair, 0xffff0000;
    ld.shared.b32 %r_pair, [%r_ibcur+148];
    shl.b32 %fi10, %r_pair, 16;
    and.b32 %fi11, %r_pair, 0xffff0000;
    ld.shared.b32 %r_pair, [%r_ibcur+216];
    shl.b32 %fi12, %r_pair, 16;
    and.b32 %fi13, %r_pair, 0xffff0000;
    ld.shared.b32 %r_pair, [%r_ibcur+220];
    shl.b32 %fi14, %r_pair, 16;
    and.b32 %fi15, %r_pair, 0xffff0000;
