    fma.rn.f32 %acc0, %fi0, %fw0, %acc0;
    fma.rn.f32 %acc0, %fi1, %fw1, %acc0;
    fma.rn.f32 %acc0, %fi2, %fw2, %acc0;
    fma.rn.f32 %acc0, %fi4, %fw3, %acc0;
    fma.rn.f32 %acc0, %fi5, %fw4, %acc0;
    fma.rn.f32 %acc0, %fi6, %fw5, %acc0;
    fma.rn.f32 %acc0, %fi8, %fw6, %acc0;
    fma.rn.f32 %acc0, %fi9, %fw7, %acc0;
    fma.rn.f32 %acc0, %fi10, %fw8, %acc0;
    fma.rn.f32 %acc1, %fi1, %fw0, %acc1;
    fma.rn.f32 %acc1, %fi2, %fw1, %acc1;
    fma.rn.f32 %acc1, %fi3, %fw2, %acc1;
    fma.rn.f32 %acc1, %fi5, %fw3, %acc1;
    fma.rn.f32 %acc1, %fi6, %fw4, %acc1;
    fma.rn.f32 %acc1, %fi7, %fw5, %acc1;
    fma.rn.f32 %acc1, %fi9, %fw6, %acc1;
    fma.rn.f32 %acc1, %fi10, %fw7, %acc1;
    fma.rn.f32 %acc1, %fi11, %fw8, %acc1;
    fma.rn.f32 %acc2, %fi4, %fw0, %acc2;
    fma.rn.f32 %acc2, %fi5, %fw1, %acc2;
    fma.rn.f32 %acc2, %fi6, %fw2, %acc2;
    fma.rn.f32 %acc2, %fi8, %fw3, %acc2;
    fma.rn.f32 %acc2, %fi9, %fw4, %acc2;
