    fma.rn.f32 %acc3, %fi15, %fw8, %acc3;
    add.u32 %r_wb, %r_wb, 36;
    add.u32 %r_ibcur, %r_ibcur, 2448;
    add.u32 %r_ic, %r_ic, 1;
    bra IC_LOOP;
IC_DONE:
    // base output element offset = ((n*32 + oc)*222 + oh0b)*222 + ow0b
